def merge_sorted_streams(*streams):
    iters = [iter(s) for s in streams]
    nexts = {}
    for i, it in enumerate(iters):
        try:
            nexts[i] = next(it)
        except StopIteration:
            pass

    while nexts:
        min_key = min(nexts[i][0] for i in nexts)
        last_val = None
        last_iter = None
        for i in nexts:
            if nexts[i][0] == min_key:
                last_val = nexts[i][1]
                last_iter = i
        yield (min_key, last_val)
        try:
            nexts[last_iter] = next(iters[last_iter])
        except StopIteration:
            del nexts[last_iter]
